20260402182632	{"-- ============================================\n-- UNIFIED USERS TABLE\n-- Combines ICPCHUE (more fields) + Verdict schemas\n-- ============================================\nCREATE TABLE IF NOT EXISTS users (\n    id                      BIGSERIAL PRIMARY KEY,\n    email                   TEXT NOT NULL UNIQUE,\n    password_hash           TEXT NOT NULL,\n    email_blind_index       TEXT,\n    \n    -- Source tracking\n    source_platform         TEXT DEFAULT 'verdict' CHECK (source_platform IN ('verdict', 'icpchue', 'merged')),\n    original_id             BIGINT,  -- Original ID from source platform\n    \n    -- Profile info\n    display_name            TEXT,\n    username                TEXT UNIQUE,\n    profile_picture_url     TEXT,\n    profile_picture         TEXT,\n    telegram_username       TEXT,\n    \n    -- University linking (new for unified platform)\n    university_id           INTEGER,\n    university_slug         TEXT,\n    faculty                 TEXT,\n    student_level           TEXT,\n    student_id_encrypted    TEXT,\n    is_university_verified  BOOLEAN DEFAULT FALSE,\n    \n    -- Application linking (from ICPCHUE)\n    application_id          BIGINT,\n    \n    -- Codeforces integration\n    codeforces_handle       TEXT,\n    codeforces_data         JSONB,\n    \n    -- Role and permissions\n    role                    TEXT DEFAULT 'member' CHECK (role IN ('trainee', 'member', 'ambassador', 'admin', 'owner')),\n    is_verified             BOOLEAN DEFAULT FALSE,\n    \n    -- Privacy settings\n    profile_visibility      TEXT DEFAULT 'public',\n    show_on_cf_leaderboard  BOOLEAN DEFAULT TRUE,\n    show_on_sheets_leaderboard BOOLEAN DEFAULT TRUE,\n    show_on_leaderboard     BOOLEAN DEFAULT TRUE,\n    show_public_profile     BOOLEAN DEFAULT TRUE,\n    \n    -- Anti-cheat\n    is_shadow_banned        BOOLEAN DEFAULT FALSE,\n    cheating_flags          INTEGER DEFAULT 0,\n    \n    -- Timestamps\n    last_login_at           TIMESTAMPTZ,\n    created_at              TIMESTAMPTZ DEFAULT NOW(),\n    updated_at              TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Indexes\nCREATE INDEX idx_users_email ON users(email);\nCREATE INDEX idx_users_email_blind ON users(email_blind_index);\nCREATE INDEX idx_users_username ON users(username);\nCREATE INDEX idx_users_university ON users(university_id);\nCREATE INDEX idx_users_source ON users(source_platform, original_id);\nCREATE INDEX idx_users_codeforces ON users(codeforces_handle);\n\n-- Enable RLS\nALTER TABLE users ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies\nCREATE POLICY \\"Users can view own profile\\" ON users\n    FOR SELECT USING (id = current_setting('app.current_user_id', true)::bigint);\n\nCREATE POLICY \\"Public profiles are viewable\\" ON users\n    FOR SELECT USING (show_public_profile = true AND is_shadow_banned = false);\n\nCOMMENT ON TABLE users IS 'Unified users table merging ICPCHUE and Verdict users';\nCOMMENT ON COLUMN users.source_platform IS 'Original platform: verdict, icpchue, or merged if accounts linked';\nCOMMENT ON COLUMN users.original_id IS 'Original user ID from source platform for reference';"}	create_unified_users_schema	yousefmsm75@gmail.com	\N	\N
20260402182755	{"-- ============================================\n-- UNIFIED USERS TABLE \n-- Matches both ICPCHUE + Verdict schemas for backfill\n-- ============================================\nCREATE TABLE users (\n    id                          BIGSERIAL PRIMARY KEY,\n    email                       TEXT NOT NULL,\n    password_hash               TEXT,  -- Verdict has this, ICPCHUE doesn't\n    email_blind_index           TEXT,\n    \n    -- Source tracking\n    source_platform             TEXT DEFAULT 'verdict' CHECK (source_platform IN ('verdict', 'icpchue', 'merged')),\n    original_id                 BIGINT,\n    \n    -- Auth linking\n    supabase_uid                UUID,  -- ICPCHUE uses this\n    auth_id                     UUID,  -- Verdict uses this\n    \n    -- Application (ICPCHUE)\n    application_id              BIGINT,\n    \n    -- Profile\n    profile_picture             VARCHAR(100),\n    profile_picture_url         TEXT,\n    telegram_username           TEXT,\n    \n    -- Codeforces\n    codeforces_handle           TEXT,\n    codeforces_data             JSONB,\n    codeforces_access_token     VARCHAR(255),\n    codeforces_refresh_token    VARCHAR(255),\n    \n    -- Role & Permissions\n    role                        TEXT DEFAULT 'member',\n    is_verified                 BOOLEAN DEFAULT FALSE,\n    profile_visibility          TEXT DEFAULT 'public',\n    \n    -- Privacy settings (ICPCHUE)\n    show_on_cf_leaderboard      BOOLEAN DEFAULT TRUE,\n    show_on_sheets_leaderboard  BOOLEAN DEFAULT TRUE,\n    show_public_profile         BOOLEAN DEFAULT TRUE,\n    \n    -- Anti-cheat (ICPCHUE)\n    is_shadow_banned            BOOLEAN DEFAULT FALSE,\n    cheating_flags              INTEGER DEFAULT 0,\n    \n    -- Verdict specific\n    tts_video_count             INTEGER DEFAULT 0,\n    \n    -- Timestamps\n    last_login_at               TIMESTAMPTZ,\n    last_login                  TIMESTAMPTZ,\n    created_at                  TIMESTAMPTZ DEFAULT NOW(),\n    updated_at                  TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Indexes\nCREATE INDEX idx_users_email ON users(email);\nCREATE INDEX idx_users_email_blind ON users(email_blind_index);\nCREATE INDEX idx_users_source ON users(source_platform, original_id);\nCREATE INDEX idx_users_codeforces ON users(codeforces_handle);\nCREATE INDEX idx_users_supabase_uid ON users(supabase_uid);\nCREATE INDEX idx_users_auth_id ON users(auth_id);\n\n-- Enable RLS\nALTER TABLE users ENABLE ROW LEVEL SECURITY;\n\n-- Service role can do everything\nCREATE POLICY \\"Enable all for service_role\\" ON users\n    TO service_role USING (true) WITH CHECK (true);\n\nCOMMENT ON TABLE users IS 'Unified users from ICPCHUE (85) + Verdict (99) backfill';"}	create_unified_schema_from_sources	yousefmsm75@gmail.com	\N	\N
20260402191817	{"-- Create sequences for tables that need them\nCREATE SEQUENCE IF NOT EXISTS news_reactions_id_seq;\nCREATE SEQUENCE IF NOT EXISTS password_resets_id_seq;\nCREATE SEQUENCE IF NOT EXISTS problem_test_cases_id_seq;\nCREATE SEQUENCE IF NOT EXISTS user_achievements_id_seq;\n\n-- Applications table\nCREATE TABLE IF NOT EXISTS public.applications (\n  id bigint GENERATED ALWAYS AS IDENTITY NOT NULL,\n  application_type text NOT NULL DEFAULT 'trainee'::text,\n  name text NOT NULL,\n  faculty text NOT NULL,\n  student_id text NOT NULL,\n  national_id text NOT NULL,\n  student_level text NOT NULL,\n  telephone text NOT NULL,\n  address text,\n  has_laptop boolean DEFAULT false,\n  codeforces_profile text,\n  leetcode_profile text,\n  leetcode_data jsonb,\n  codeforces_data jsonb,\n  scraping_status text DEFAULT 'pending'::text,\n  ip_address text,\n  user_agent text,\n  email text,\n  submitted_at timestamp with time zone DEFAULT now(),\n  telegram_username text,\n  email_hash character varying,\n  email_blind_index text,\n  national_id_blind_index text,\n  telephone_blind_index text,\n  student_id_blind_index text,\n  CONSTRAINT applications_pkey PRIMARY KEY (id)\n);\n\n-- API Access Log\nCREATE TABLE IF NOT EXISTS public.api_access_log (\n  id bigint GENERATED ALWAYS AS IDENTITY NOT NULL,\n  endpoint text NOT NULL,\n  ip_address text,\n  user_agent text,\n  method text,\n  status_code integer,\n  accessed_at timestamp with time zone DEFAULT now(),\n  CONSTRAINT api_access_log_pkey PRIMARY KEY (id)\n);\n\n-- Email verification OTPs\nCREATE TABLE IF NOT EXISTS public.email_verification_otps (\n  email character varying NOT NULL,\n  otp_code character varying NOT NULL,\n  expires_at timestamp with time zone NOT NULL,\n  created_at timestamp with time zone DEFAULT now(),\n  CONSTRAINT email_verification_otps_pkey PRIMARY KEY (email)\n);\n\n-- Login logs\nCREATE TABLE IF NOT EXISTS public.login_logs (\n  id bigint GENERATED ALWAYS AS IDENTITY NOT NULL,\n  ip_address text,\n  user_agent text,\n  logged_in_at timestamp with time zone DEFAULT now(),\n  user_id bigint,\n  CONSTRAINT login_logs_pkey PRIMARY KEY (id),\n  CONSTRAINT login_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id)\n);\n\n-- News reactions\nCREATE TABLE IF NOT EXISTS public.news_reactions (\n  id integer NOT NULL DEFAULT nextval('news_reactions_id_seq'::regclass),\n  news_id character varying NOT NULL,\n  user_id integer NOT NULL,\n  reaction_type character varying NOT NULL CHECK (reaction_type::text = ANY (ARRAY['like'::character varying, 'heart'::character varying, 'fire'::character varying]::text[])),\n  created_at timestamp without time zone DEFAULT now(),\n  CONSTRAINT news_reactions_pkey PRIMARY KEY (id)\n);\n\n-- Page views\nCREATE TABLE IF NOT EXISTS public.page_views (\n  entity_type character varying NOT NULL,\n  entity_id character varying NOT NULL,\n  views_count bigint DEFAULT 0,\n  CONSTRAINT page_views_pkey PRIMARY KEY (entity_type, entity_id)\n);\n\n-- Password resets\nCREATE TABLE IF NOT EXISTS public.password_resets (\n  id integer NOT NULL DEFAULT nextval('password_resets_id_seq'::regclass),\n  email character varying NOT NULL,\n  token_hash text NOT NULL,\n  expires_at timestamp without time zone NOT NULL,\n  created_at timestamp without time zone DEFAULT now(),\n  used boolean DEFAULT false,\n  CONSTRAINT password_resets_pkey PRIMARY KEY (id)\n);\n\n-- Problem test cases\nCREATE TABLE IF NOT EXISTS public.problem_test_cases (\n  id integer NOT NULL DEFAULT nextval('problem_test_cases_id_seq'::regclass),\n  sheet_id text NOT NULL,\n  problem_id text NOT NULL,\n  input text NOT NULL,\n  expected_output text NOT NULL,\n  is_sample boolean DEFAULT false,\n  is_hidden boolean DEFAULT false,\n  ordinal integer NOT NULL DEFAULT 0,\n  created_at timestamp without time zone DEFAULT now(),\n  CONSTRAINT problem_test_cases_pkey PRIMARY KEY (id)\n);\n\n-- Recap 2025\nCREATE TABLE IF NOT EXISTS public.recap_2025 (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  student_id text NOT NULL,\n  username text NOT NULL,\n  avatar_url text,\n  days_active integer DEFAULT 0,\n  total_solved integer DEFAULT 0,\n  total_submissions integer DEFAULT 0,\n  top_problem text,\n  top_problem_attempts integer DEFAULT 0,\n  rank_percentile integer DEFAULT 100,\n  max_streak integer DEFAULT 0,\n  preferred_language text DEFAULT 'C++'::text,\n  top_tags jsonb DEFAULT '[]'::jsonb,\n  difficulty_solved jsonb DEFAULT '{\\"easy\\": 0, \\"hard\\": 0, \\"medium\\": 0}'::jsonb,\n  achievements jsonb DEFAULT '[]'::jsonb,\n  created_at timestamp with time zone DEFAULT now(),\n  updated_at timestamp with time zone DEFAULT now(),\n  time_spent_minutes integer DEFAULT 0,\n  CONSTRAINT recap_2025_pkey PRIMARY KEY (id),\n  CONSTRAINT recap_2025_student_id_key UNIQUE (student_id)\n);\n\n-- Training submissions\nCREATE TABLE IF NOT EXISTS public.training_submissions (\n  id bigint GENERATED ALWAYS AS IDENTITY NOT NULL,\n  user_id bigint NOT NULL,\n  sheet_id text NOT NULL,\n  problem_id text NOT NULL,\n  source_code text NOT NULL,\n  language text DEFAULT 'C++20 (GCC 13-64)'::text,\n  verdict text NOT NULL,\n  time_ms integer,\n  memory_kb integer,\n  test_cases_passed integer DEFAULT 0,\n  total_test_cases integer DEFAULT 0,\n  compile_error text,\n  runtime_error text,\n  submitted_at timestamp with time zone DEFAULT now(),\n  ip_address text,\n  tab_switches integer DEFAULT 0,\n  paste_events integer DEFAULT 0,\n  time_to_solve_seconds integer,\n  attempt_number integer DEFAULT 1,\n  CONSTRAINT training_submissions_pkey PRIMARY KEY (id),\n  CONSTRAINT training_submissions_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id)\n);\n\n-- User achievements\nCREATE TABLE IF NOT EXISTS public.user_achievements (\n  id integer NOT NULL DEFAULT nextval('user_achievements_id_seq'::regclass),\n  user_id bigint,\n  achievement_id text NOT NULL,\n  earned_at timestamp with time zone DEFAULT now(),\n  seen boolean DEFAULT false,\n  CONSTRAINT user_achievements_pkey PRIMARY KEY (id),\n  CONSTRAINT user_achievements_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id)\n);\n\n-- View logs\nCREATE TABLE IF NOT EXISTS public.view_logs (\n  id bigint GENERATED ALWAYS AS IDENTITY NOT NULL,\n  user_id bigint NOT NULL,\n  entity_type character varying NOT NULL,\n  entity_id character varying NOT NULL,\n  created_at timestamp with time zone DEFAULT now(),\n  CONSTRAINT view_logs_pkey PRIMARY KEY (id)\n);\n\n-- Website analytics\nCREATE TABLE IF NOT EXISTS public.website_analytics (\n  id bigint GENERATED ALWAYS AS IDENTITY NOT NULL,\n  path text NOT NULL,\n  ip_address text,\n  user_agent text,\n  referer text,\n  session_id text,\n  country text,\n  device_type text,\n  browser text,\n  os text,\n  visited_at timestamp with time zone DEFAULT now(),\n  CONSTRAINT website_analytics_pkey PRIMARY KEY (id)\n);"}	create_icpchue_tables	yousefmsm75@gmail.com	\N	\N
20260403112803	{"-- Drop and recreate email_verification_otps with correct structure\nDROP TABLE IF EXISTS public.email_verification_otps;\n\nCREATE TABLE public.email_verification_otps (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  email_blind_index text NOT NULL UNIQUE,\n  otp_hash text NOT NULL,\n  expires_at timestamp with time zone NOT NULL,\n  attempts integer DEFAULT 0,\n  verified_at timestamp with time zone,\n  created_at timestamp with time zone DEFAULT now()\n);"}	fix_email_verification_otps_table	yousefmsm75@gmail.com	\N	\N
20260403141245	{"-- Add missing columns to users table\nALTER TABLE users ADD COLUMN IF NOT EXISTS tier TEXT DEFAULT 'public' CHECK (tier IN ('public', 'university'));\nALTER TABLE users ADD COLUMN IF NOT EXISTS name TEXT;\nALTER TABLE users ADD COLUMN IF NOT EXISTS university_id BIGINT;\nALTER TABLE users ADD COLUMN IF NOT EXISTS leetcode_handle TEXT;\nALTER TABLE users ADD COLUMN IF NOT EXISTS is_email_verified BOOLEAN DEFAULT false;\n\n-- Create universities table\nCREATE TABLE IF NOT EXISTS universities (\n    id BIGSERIAL PRIMARY KEY,\n    name TEXT NOT NULL,\n    short_name TEXT,\n    email_domain TEXT NOT NULL UNIQUE,\n    logo_url TEXT,\n    is_active BOOLEAN DEFAULT true,\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Insert Horus University\nINSERT INTO universities (name, short_name, email_domain, is_active)\nVALUES ('Horus University', 'HUE', 'horus.edu.eg', true)\nON CONFLICT (email_domain) DO NOTHING;\n\n-- Create achievements table\nCREATE TABLE IF NOT EXISTS achievements (\n    id BIGSERIAL PRIMARY KEY,\n    name TEXT NOT NULL UNIQUE,\n    description TEXT,\n    icon TEXT,\n    points INTEGER DEFAULT 0,\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Insert First Steps achievement\nINSERT INTO achievements (name, description, icon, points)\nVALUES ('First Steps', 'Registered and completed your profile', 'trophy', 10)\nON CONFLICT (name) DO NOTHING;\n\n-- Create user_streaks table\nCREATE TABLE IF NOT EXISTS user_streaks (\n    user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,\n    current_streak INTEGER DEFAULT 0,\n    longest_streak INTEGER DEFAULT 0,\n    last_activity_date DATE,\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Add user_id and university_id to applications table\nALTER TABLE applications ADD COLUMN IF NOT EXISTS user_id BIGINT REFERENCES users(id) ON DELETE CASCADE;\nALTER TABLE applications ADD COLUMN IF NOT EXISTS university_id BIGINT REFERENCES universities(id);\nALTER TABLE applications ADD COLUMN IF NOT EXISTS status TEXT DEFAULT 'pending';\nALTER TABLE applications ADD COLUMN IF NOT EXISTS leetcode_handle TEXT;\nALTER TABLE applications ADD COLUMN IF NOT EXISTS codeforces_handle TEXT;"}	add_missing_columns_and_tables	yousefmsm75@gmail.com	\N	\N
20260403155933	{"\n-- Create curriculum_levels table\nCREATE TABLE IF NOT EXISTS public.curriculum_levels (\n  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  level_number INTEGER NOT NULL UNIQUE,\n  name VARCHAR(100) NOT NULL,\n  slug VARCHAR(50) NOT NULL UNIQUE,\n  description TEXT,\n  duration_weeks INTEGER,\n  total_problems INTEGER DEFAULT 0,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Create indexes\nCREATE INDEX IF NOT EXISTS idx_curriculum_levels_slug ON public.curriculum_levels(slug);\n"}	create_curriculum_levels	yousefmsm75@gmail.com	\N	\N
20260403155939	{"\n-- Create curriculum_sheets table\nCREATE TABLE IF NOT EXISTS public.curriculum_sheets (\n  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  level_id BIGINT NOT NULL REFERENCES public.curriculum_levels(id) ON DELETE CASCADE,\n  sheet_letter VARCHAR(10) NOT NULL,\n  sheet_number INTEGER NOT NULL,\n  name VARCHAR(200) NOT NULL,\n  slug VARCHAR(50) NOT NULL,\n  description TEXT,\n  contest_id VARCHAR(50),\n  contest_url TEXT,\n  total_problems INTEGER DEFAULT 0,\n  group_id VARCHAR(255),\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(level_id, sheet_letter),\n  UNIQUE(level_id, sheet_number)\n);\n\n-- Create indexes\nCREATE INDEX IF NOT EXISTS idx_curriculum_sheets_level_id ON public.curriculum_sheets(level_id);\nCREATE INDEX IF NOT EXISTS idx_curriculum_sheets_slug ON public.curriculum_sheets(slug);\nCREATE INDEX IF NOT EXISTS idx_curriculum_sheets_contest ON public.curriculum_sheets(contest_id) WHERE contest_id IS NOT NULL;\n"}	create_curriculum_sheets	yousefmsm75@gmail.com	\N	\N
20260403155944	{"\n-- Create curriculum_problems table\nCREATE TABLE IF NOT EXISTS public.curriculum_problems (\n  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  sheet_id BIGINT NOT NULL REFERENCES public.curriculum_sheets(id) ON DELETE CASCADE,\n  problem_number INTEGER NOT NULL,\n  problem_letter VARCHAR(5) NOT NULL,\n  title VARCHAR(300) NOT NULL,\n  codeforces_url TEXT NOT NULL,\n  content JSONB,\n  solution_video_url TEXT,\n  rating INTEGER,\n  contest_id TEXT,\n  UNIQUE(sheet_id, problem_letter),\n  UNIQUE(sheet_id, problem_number)\n);\n\n-- Create indexes\nCREATE INDEX IF NOT EXISTS idx_curriculum_problems_sheet_id ON public.curriculum_problems(sheet_id);\nCREATE INDEX IF NOT EXISTS idx_curriculum_problems_letter ON public.curriculum_problems(problem_letter);\n"}	create_curriculum_problems	yousefmsm75@gmail.com	\N	\N
20260403160413	{"\n-- Create user_progress table\nCREATE TABLE IF NOT EXISTS public.user_progress (\n  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id BIGINT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  problem_id VARCHAR(255) NOT NULL,\n  sheet_id VARCHAR(255),\n  status VARCHAR(50) NOT NULL DEFAULT 'SOLVED',\n  submission_id BIGINT UNIQUE,\n  solved_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(user_id, problem_id),\n  CONSTRAINT chk_progress_status CHECK (status IN ('SOLVED', 'ATTEMPTED'))\n);\n\n-- Create indexes\nCREATE INDEX IF NOT EXISTS idx_user_progress_user_id ON public.user_progress(user_id);\nCREATE INDEX IF NOT EXISTS idx_user_progress_problem_id ON public.user_progress(problem_id);\nCREATE INDEX IF NOT EXISTS idx_user_progress_user_status ON public.user_progress(user_id, status);\nCREATE INDEX IF NOT EXISTS idx_user_progress_sheet_status ON public.user_progress(sheet_id, status) WHERE sheet_id IS NOT NULL;\n"}	create_user_progress	yousefmsm75@gmail.com	\N	\N
20260403160705	{"\n-- Create cf_submissions table\nCREATE TABLE IF NOT EXISTS public.cf_submissions (\n  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  user_id BIGINT NOT NULL REFERENCES public.users(id),\n  cf_submission_id BIGINT NOT NULL UNIQUE,\n  contest_id VARCHAR NOT NULL,\n  problem_index VARCHAR NOT NULL,\n  sheet_id VARCHAR,\n  verdict VARCHAR NOT NULL,\n  time_ms INTEGER DEFAULT 0,\n  memory_kb INTEGER DEFAULT 0,\n  language VARCHAR,\n  source_code TEXT,\n  cf_handle VARCHAR,\n  url_type VARCHAR DEFAULT 'contest',\n  group_id VARCHAR,\n  submitted_at TIMESTAMPTZ DEFAULT now(),\n  details TEXT,\n  test_number INTEGER,\n  compilation_error TEXT,\n  notes TEXT,\n  note_color VARCHAR(20)\n);\n\n-- Create indexes\nCREATE INDEX IF NOT EXISTS idx_cf_sub_user_id ON public.cf_submissions(user_id);\nCREATE INDEX IF NOT EXISTS idx_cf_sub_verdict ON public.cf_submissions(verdict);\nCREATE INDEX IF NOT EXISTS idx_cf_sub_user_verdict ON public.cf_submissions(user_id, verdict);\nCREATE INDEX IF NOT EXISTS idx_cf_sub_submitted_at ON public.cf_submissions(submitted_at DESC);\nCREATE INDEX IF NOT EXISTS idx_cf_sub_user_contest ON public.cf_submissions(user_id, contest_id, problem_index);\nCREATE INDEX IF NOT EXISTS idx_cf_sub_contest_verdict ON public.cf_submissions(contest_id, verdict);\nCREATE INDEX IF NOT EXISTS idx_cf_sub_sheet_verdict ON public.cf_submissions(sheet_id, verdict) WHERE sheet_id IS NOT NULL;\n"}	create_cf_submissions	yousefmsm75@gmail.com	\N	\N
20260403160957	{"\n-- Create daily_solves table\nCREATE TABLE IF NOT EXISTS public.daily_solves (\n  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  user_id BIGINT NOT NULL REFERENCES public.users(id),\n  solve_date DATE NOT NULL DEFAULT CURRENT_DATE,\n  solve_count INTEGER DEFAULT 0,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(user_id, solve_date)\n);\n\n-- Create indexes\nCREATE INDEX IF NOT EXISTS idx_daily_solves_user_date ON public.daily_solves(user_id, solve_date);\n"}	create_daily_solves	yousefmsm75@gmail.com	\N	\N
20260403161250	{"\n-- Create notifications table\nCREATE TABLE IF NOT EXISTS public.notifications (\n  id SERIAL PRIMARY KEY,\n  user_id BIGINT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  title TEXT NOT NULL,\n  message TEXT NOT NULL,\n  type TEXT NOT NULL,\n  is_read BOOLEAN DEFAULT false,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  CONSTRAINT chk_notification_type CHECK (type IN ('achievement', 'leaderboard', 'system'))\n);\n\n-- Create indexes\nCREATE INDEX IF NOT EXISTS idx_notifications_user_id ON public.notifications(user_id);\nCREATE INDEX IF NOT EXISTS idx_notifications_created_at ON public.notifications(created_at DESC);\n"}	create_notifications	yousefmsm75@gmail.com	\N	\N
